import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:plezy/services/app_icon/app_icon_catalog.dart';

/// The catalog ids are the platform names devices persist, and every asset
/// behind them is generated by scripts/codegen/generate_app_icons.py. These
/// tests fail when an id has no switchable icon on some platform, which would
/// otherwise only show up as a refused switch on a device.
void main() {
  final alternates = [
    for (final option in appIconCatalog)
      if (!option.isDefault) option.id,
  ];

  test('the default icon comes first and every id is unique', () {
    expect(appIconCatalog.first.id, defaultAppIconId);
    expect(appIconCatalog.map((option) => option.id).toSet(), hasLength(appIconCatalog.length));
    expect(alternates, hasLength(23));
  });

  test('Android declares exactly one launcher alias per alternate, next to the default .MainActivity', () {
    final manifest = File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    final declared = RegExp(r'android:name="\.appicon\.([a-z0-9_]+)"').allMatches(manifest).map((m) => m[1]).toList();

    expect(declared, unorderedEquals(alternates));
    expect(manifest, contains('android:name=".MainActivity"'));
  });

  test('every alternate has its Android icon layers, legacy icon and TV banner', () {
    const res = 'android/app/src/main/res';
    for (final id in alternates) {
      final files = [
        '$res/mipmap-anydpi-v26/ic_launcher_$id.xml',
        '$res/mipmap-xxxhdpi/ic_launcher_$id.webp',
        '$res/drawable-xhdpi/tv_banner_$id.webp',
        for (final density in ['xhdpi', 'xxhdpi', 'xxxhdpi'])
          for (final layer in ['background', 'foreground', 'monochrome'])
            '$res/drawable-$density/ic_launcher_${id}_$layer.webp',
      ];
      for (final path in files) {
        expect(File(path).existsSync(), isTrue, reason: '$id is missing $path');
      }
    }
  });

  test('every alternate has an iOS icon set and a layered tvOS image stack', () {
    for (final id in alternates) {
      final ios = File('ios/Runner/AlternateAppIcons.xcassets/AppIcon-$id.appiconset/icon.png');
      expect(ios.existsSync(), isTrue, reason: '$id is missing ${ios.path}');

      for (final layer in ['Front', 'Back']) {
        final imageset = Directory(
          'tvos/Runner/AlternateAppIcons.xcassets/AppIcon-$id.imagestack/$layer.imagestacklayer/Content.imageset',
        );
        final images = imageset.existsSync()
            ? imageset.listSync().where((entry) => entry.path.endsWith('.png')).toList()
            : const <FileSystemEntity>[];
        expect(images, isNotEmpty, reason: '$id is missing its tvOS $layer layer in ${imageset.path}');
      }
    }
  });

  test('every alternate has a bundled picker thumbnail', () {
    for (final option in appIconCatalog.where((option) => !option.isDefault)) {
      expect(File(option.previewAsset!).existsSync(), isTrue, reason: '${option.id} has no picker thumbnail');
    }
  });

  test('the default has a thumbnail for each TV launcher, which draws it on a dark plate', () {
    for (final preview in [defaultAppIconTvosPreview, defaultAppIconAndroidTvPreview]) {
      expect(File(preview).existsSync(), isTrue, reason: 'missing $preview');
    }
  });
}
